def rle_encode(s):
    if not s:
        return ""
    result = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            result.append(f"{count}{s[i - 1]}")
            count = 1
    result.append(f"{count}{s[-1]}")
    return "".join(result)

def rle_decode(s):
    if not s:
        return ""
    result = []
    i = 0
    while i < len(s):
        # Read digits for the count
        j = i
        while j < len(s) and s[j].isdigit():
            j += 1
        count = int(s[i:j])
        char = s[j]
        result.append(char * count)
        i = j + 1
    return "".join(result)
